(() => {
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,route,primary=false)=>`<a class="button${primary?' primary':''}" href="#${route}">${label}</a>`;
const action=(label,modal,primary=false)=>`<button type="button" class="button${primary?' primary':''}" data-modal="${modal}">${label}</button>`;
window.U={head:(kicker,title,description,actions='')=>`<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`,button,action,badge:(text,tone='neutral')=>`<span class="badge ${tone}">${text}</span>`,tabs:(items,active)=>`<nav class="tabs" aria-label="Section navigation">${items.map(([label,route])=>`<a href="#${route}"${route===active?' aria-current="page"':''}>${label}</a>`).join('')}</nav>`,row:(title,meta,route,end='')=>`<div class="row"><a class="row-main" href="#${route}"><div class="row-title">${title}</div><div class="row-meta">${meta}</div></a>${end?`<div class="end">${end}</div>`:`<a class="icon-button" href="#${route}" aria-label="Open ${esc(title)}">→</a>`}</div>`,field:(label,control,hint='')=>`<label class="field"><span>${label}</span>${control}${hint?`<small>${hint}</small>`:''}</label>`,input:(name,value='',type='text')=>`<input name="${name}" value="${esc(value)}" type="${type}"${type==='number'?' min="0" step="any"':''}>`,select:(name,options)=>`<select name="${name}">${options.map(x=>`<option>${esc(x)}</option>`).join('')}</select>`};
window.U.head=(kicker,title,description='',actions='')=>`<div class="page-head"><div>${kicker?`<div class="eyebrow">${kicker}</div>`:''}<h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const singleField=window.U.field;
window.U.field=(label,control,hint='')=>control.includes('<label')?`<fieldset class="field" style="border:0;padding:0;margin:0"><legend>${label}</legend>${control}${hint?`<small>${hint}</small>`:''}</fieldset>`:singleField(label,control,hint);
const {head,field,input,select,badge}=window.U;
let role='member',lastFocus=null,toastTimer,route='home',checkedIn=false;
const nav=[['home','Home'],['work','Tasks'],['activities','Activities'],['hours','Season hours'],['team','Team'],['docs','Docs']];
const primaryFor=r=>r.startsWith('work')||r.startsWith('task')?'work':['hours','team-hours'].includes(r)?'hours':['activities','build','build-attendance','checkin','outreach','outreach-log','event','attendance','activity-history'].includes(r)?'activities':r.startsWith('profile-')||r.startsWith('member-')||['team','members','member','setup','reports','settings','reviews','individual-review'].includes(r)?'team':r;
const groupNav=()=>{let links=[['submissions','My submissions'],['notifications','Notifications'],['profile','My profile']];if(['admin','president'].includes(role))links.push(['reviews','Reviews']);return links;};
const iconSVG=name=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-8h6v8"/>',work:'<path d="m3 6 2 2 3-4M11 6h10M3 13h4M11 13h10M3 20h4M11 20h10"/>',activities:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M7 15h2M15 15h2"/>',scouting:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 1v4M12 19v4M1 12h4M19 12h4"/>',team:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 4v3"/>',hours:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',submissions:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 12h7M9 16h7"/>',notifications:'<path d="M6 9a6 6 0 0 1 12 0c0 7 3 7 3 9H3c0-2 3-2 3-9M10 21h4"/>',reviews:'<path d="m4 12 5 5L20 6"/>',more:'<path d="M4 6h16M4 12h16M4 18h16"/>'})[name]||'<circle cx="12" cy="12" r="8"/>'}</svg>`;
const extraIcons={refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-2l2 2M18 17a7 7 0 0 1-12 2l-2-2"/>',qr:'<path d="M3 3h6v6H3zM15 3h6v6h-6zM3 15h6v6H3zM15 15h2v2h-2zM19 15h2v6h-6v-2"/>',location:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',edit:'<path d="m15 4 5 5M4 20l4-1L21 6l-5-5L3 14z"/>',board:'<rect x="3" y="4" width="5" height="16" rx="1"/><rect x="10" y="4" width="5" height="11" rx="1"/><rect x="17" y="4" width="4" height="14" rx="1"/>',filter:'<path d="M3 5h18l-7 8v6l-4 2v-8z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',docs:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3zM12 6v15"/>'};
window.U.icon=name=>extraIcons[name]?`<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${extraIcons[name]}</svg>`:iconSVG(({list:'work',calendar:'activities',check:'reviews',profile:'team'})[name]||name);
function navHTML(items,active){return items.map(([r,label])=>r==='docs'?`<span class="nav-link reserved-nav" aria-label="Docs, outside this design review"><span class="nav-icon">${window.U.icon('docs')}</span><span>Docs</span><small>Not in review</small></span>`:`<a class="nav-link" href="#${r}"${active===r?' aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${window.U.icon(r)}</span><span>${label}</span>${r==='reviews'?'<span class="nav-count">5</span>':''}</a>`).join('');}
function notify(message){let toast=document.querySelector('#toast');toast.textContent=message;toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),6500);}
function render(){route=location.hash.slice(1).split('?')[0]||'home';if(route==='guide'||route.startsWith('scout')||route==='docs')route='home';const screen=window.screens[route];document.querySelector('#main').innerHTML=screen?screen({role}):head('Toolkit','Page not in this review','',button('Home','home'));document.querySelector('#primary-nav').innerHTML=navHTML(nav,primaryFor(route));document.querySelector('#secondary-nav').innerHTML=navHTML(groupNav(),route);document.querySelector('.account-nav').open=false;document.querySelector('#role-caption').textContent={member:'Member',lead:'Event lead',admin:'Officer · Granted access',president:'President'}[role];document.title=`${document.querySelector('h1')?.textContent||'Toolkit'} · Optix design`;
if(route==='checkin'&&checkedIn)renderCheckedIn();
if(checkedIn&&['home','build','activities'].includes(route)){document.querySelectorAll('#main a[href="#checkin"]').forEach(a=>a.textContent='Check out');const strip=document.createElement('div');strip.className='notice';strip.innerHTML=`<div><strong>You’re checked in · Workshop</strong><p>Sample arrival 3:35 PM PST · Check out when you leave.</p></div>${button('Check out','checkin',true)}`;if(route==='home')document.querySelector('#main .page-head + .notice')?.replaceWith(strip);else document.querySelector('#main .page-head')?.after(strip);}
document.querySelectorAll('select[name=history-type]').forEach(x=>x.setAttribute('aria-label','Attendance type'));
document.querySelectorAll('select[name=history-season]').forEach(x=>x.setAttribute('aria-label','Attendance season'));
for(const table of document.querySelectorAll('.table-wrap:not([tabindex])')){table.tabIndex=0;table.setAttribute('role','region');table.setAttribute('aria-label','Scrollable data table');}
for(const label of document.querySelectorAll('label.field')){const controls=label.querySelectorAll('input,select,textarea');if(controls.length>1){const span=label.querySelector(':scope > span');if(span){const wrapper=document.createElement('fieldset');wrapper.className='field';wrapper.style.cssText='border:0;margin:0;padding:0';wrapper.innerHTML=label.innerHTML.replace(/^<span>(.*?)<\/span>/,'<legend>$1</legend>');label.replaceWith(wrapper);}}}
document.dispatchEvent(new CustomEvent('prototype:render',{detail:{route,role}}));}
window.renderPrototype=render;
const confirm=(text,label='Confirm')=>`<p>${text}</p><form class="stack" style="margin-top:18px" data-confirm-form="${esc(label)}"><button class="button primary" type="submit">${label}</button><button type="button" class="button" data-close>Cancel</button></form>`;
const feed=()=>field('Feedback (required)','<textarea name="decision-feedback" required placeholder="Explain what needs to change or why this is rejected"></textarea>');
const decision=(title,approve=false)=>`<form class="stack" data-confirm-form="${title}">${!approve?feed():field('Decision note (optional)','<textarea name="decision-note"></textarea>')}<button class="button primary" type="submit">${title}</button></form>`;
const modalDefs={
 'task-filters':['Task filters',`<form class="stack" data-filter-form>${field('Scope',select('scope',['Assigned to me','All group work','Assigned reviews']))}${field('Status',select('status',['Active','Changes requested','Assigned','In progress','Submitted','Resubmitted','Completed','Cancelled','All statuses']))}${field('Category',select('category',['All categories','Robot development','Outreach']))}<fieldset style="border:1px solid var(--line);border-radius:5px"><legend class="small">Owning member groups</legend><label class="checkline"><input type="checkbox" checked name="group-software">Software</label><label class="checkline"><input type="checkbox" checked name="group-outreach">Outreach</label><label class="checkline"><input type="checkbox" name="group-mechanical">Mechanical</label><button type="button" class="button" data-clear-groups>Clear all</button></fieldset><button class="button primary">Apply filters</button></form>`],
 'submit-task':['Resubmit for review',`<form class="stack" data-confirm-form="Task resubmitted">${field('Submission note (optional)','<textarea name="submission-note"></textarea>')}<button class="button primary">Resubmit</button></form>`],
 'task-evidence':['Add evidence',`<form class="stack" data-demo-form="Evidence added">${field('Link',input('evidence-link','','url'))}${field('Picture','<input type="file" name="evidence-picture" accept="image/*">')}<button class="button primary">Add evidence</button></form>`],
 'task-start':['Start assigned task',confirm('Assigned → In progress. Work and evidence remain available.','Start task')],
 'task-complete':['Complete without review',confirm('For tasks that do not require review, completion does not create a review queue item.','Complete task')],
 'task-reopen':['Reopen task',confirm('Reopening keeps prior work, submissions and review history.','Reopen task')],
 'cancel-task':['Cancel task',confirm('Cancellation retains operational history. It is not deletion.','Cancel task')],
 'task-assignees':['Transfer task',`<form class="stack" data-confirm-form="Task group transferred">${field('Owning group',select('transfer-group',['Software','Mechanical','Outreach']))}<p class="small muted">Assignees update to the new group. Existing work is retained.</p><button class="button primary">Transfer</button></form>`],
 'evidence-settings':['Evidence limits',`<form class="stack" data-demo-form="Evidence limits updated in this prototype only.">${field('Allowed MIME types',input('evidence-mime','image/jpeg,image/png,image/webp'))}${field('Maximum bytes',input('evidence-max','10485760','number'))}<button class="button primary">Save limits</button></form>`],
 'override-complete':['Override completion',`<form class="stack" data-confirm-form="Task completed by management override">${feed()}<button class="button primary">Complete task</button></form>`],
 'request-changes':['Request changes',decision('Request changes')], 'reject-review':['Reject initiative',decision('Reject initiative')], 'approve-review':['Approve task',decision('Approve task',true)],'approve-opi':['Approve initiative',decision('Approve initiative',true)],'approve-purchase':['Approve purchase · $38.40',confirm('This commits the final approval decision for the reimbursement or purchase-order request. It does not process payment.','Approve purchase')],'reject-purchase':['Reject purchase',confirm('This commits the final rejection decision. No new persisted feedback field is introduced.','Reject purchase')],
 'review-history':['Retained review history',`<ol class="timeline"><li><strong>Version 2 · Submitted Nov 1</strong><p>Updated evidence and repeatability measurements.</p></li><li><strong>Version 1 · Changes requested Oct 30</strong><p>Record five trials and attach results.</p></li></ol>`],
 'calendar-month':['Calendar navigation',`<p>The design keeps month navigation above the calendar. This sample month is November 2026; no other month’s records are included.</p><div class="actions" style="margin-top:18px">${button('Return to November','work-calendar')}${button('View all tasks','work')}</div>`],
 'activity-new':['Schedule activity',`<div class="stack">${action('Build session','edit-session',true)}${action('Outreach event','event-edit')}</div>`],
 'edit-session':['Build session configuration',`<form class="stack" data-demo-form="Session configuration saved in this prototype only."><div class="form-grid">${field('Title',input('session-title','Workshop build'))}${field('Season',select('session-season',['2026–27','2025–26']))}${field('Location',select('session-location',['Workshop','Annex']))}${field('Opens (Los Angeles)',input('session-start','2026-11-02T15:30','datetime-local'))}${field('Closes (Los Angeles)',input('session-end','2026-11-02T18:00','datetime-local'))}</div><details><summary>Ambiguous daylight-saving times</summary><div>${field('If this wall time occurs twice',select('dst-choice',['Reject ambiguity (default)','Earlier occurrence','Later occurrence']))}<p class="small muted">Nonexistent wall times must be corrected; do not silently shift saved timestamps.</p></div></details><button class="button primary">Save session</button></form><details style="margin-top:18px"><summary>Cancel / restore session</summary><div><p class="small muted">Preserve attendance and retained history.</p><div class="actions">${action('Confirm cancellation','cancel-session')}${action('Restore cancelled session','restore-session')}</div></div></details>`],
 'cancel-session':['Cancel build session',confirm('The session is cancelled, not deleted. Preserve existing attendance.','Cancel session')],
 'restore-session':['Restore build session',confirm('Restore the cancelled session under existing authorization and time rules.','Restore session')],
 'build-qr':['Display rotating check-in QR',`<div class="proof" style="min-height:180px"><div><strong>QR DISPLAY AREA</strong><p class="small">Non-scannable design illustration<br>No live token or real check-in link</p></div></div><p class="small muted" style="margin-top:16px">Workshop · Expires in 45 seconds in the application. Rotation stays opt-in and clearly visible.</p><label class="checkline"><input type="checkbox" checked name="rotate-qr">Rotate automatically</label><div class="actions">${action('Generate fresh sample display','fresh-qr')}${button('Preview member scan','checkin')}</div>`],
 'fresh-qr':['Fresh QR display',`<p>Sample display refreshed. In the application, generate a new expiring token and restart its countdown; never keep an expired code looking valid.</p>${button('Member check-in','checkin')}`],
 'scan-qr':['Scan QR · Workshop',`<div class="camera-sample"><div class="scan-frame"></div><span>Camera preview · Sample</span></div><div class="session-match"><strong>Workshop</strong>${badge('Code recognized','success')}<span>Today · 3:30–6:00 PM PST</span></div><form data-checkin><button class="button primary">Confirm check-in</button></form>`],
 'gps-checkin':['Use location · Workshop',`<div class="location-result"><span>${window.U.icon('location')}</span><strong>Within Workshop zone</strong>${badge('Sample location','success')}</div><form data-checkin><button class="button primary">Confirm check-in</button></form>`],
 'build-location':['Build locations & GPS zones',`<form class="stack" data-demo-form="Build location saved in this prototype only.">${field('Location name',input('zone-name','Workshop'))}<details open><summary>Optional GPS geofence</summary><div class="stack">${field('Latitude',input('latitude','37.35','number'))}${field('Longitude','<input type="number" name="longitude" step="any" value="-121.95">')}${field('Radius (meters)',input('radius','100','number'))}<p class="small muted">Configure all three values together or omit them all. QR check-in works without GPS.</p></div></details><button class="button primary">Save location</button></form>`],
 'scheduler-health':['Automatic checkout',`<div class="notice"><strong>Scheduler active</strong><span>Checks every minute</span></div><div class="actions" style="margin-top:20px"><button class="icon-button" title="Refresh scheduler status" aria-label="Refresh scheduler status" data-notice="Status refreshed">${window.U.icon('refresh')}</button></div>`],
 'event-edit':['Outreach event configuration',`<form class="stack" data-demo-form="Event configuration saved in this prototype only."><div class="form-grid">${field('Title',input('event-title','Library robotics day'))}${field('Season',select('event-season',['2026–27','2025–26']))}${field('Location',input('event-location','Central Library'))}${field('Starts (Los Angeles)',input('event-start','2026-11-07T10:00','datetime-local'))}${field('Ends (Los Angeles)',input('event-end','2026-11-07T12:00','datetime-local'))}<div class="wide">${field('Description','<textarea name="event-description">Hands-on robot demonstration and design challenge.</textarea>')}</div></div><details><summary>Coordinates, leads & attendance-sensitive edits</summary><div class="stack">${field('Latitude','<input type="number" name="event-lat" step="any">')}${field('Longitude','<input type="number" name="event-lng" step="any">')}<p class="small muted">Coordinates are optional as a pair; they do not enable outreach self-check-in.</p><label class="checkline"><input type="checkbox" checked name="event-lead-maya">Assign Maya Patel as event lead</label><label class="checkline"><input type="checkbox" checked name="event-lead-jordan">Assign Jordan Lee as event lead</label><p class="small muted">If edits conflict with recorded attendance, show affected records and require authorized corrections in the same operation. Do not silently clamp or erase history.</p>${action('Open attendance corrections','record-attendance')}${field('Ambiguous wall time',select('event-dst',['Reject ambiguity','Earlier occurrence','Later occurrence']))}</div></details><button class="button primary">Save event</button></form><details style="margin-top:18px"><summary>Cancel / restore event</summary><div class="actions">${action('Cancel event','cancel-event')}${action('Restore cancelled event','restore-event')}</div></details>`],
 'cancel-event':['Cancel outreach event',confirm('Cancellation keeps event history and attendance.','Cancel event')], 'restore-event':['Restore outreach event',confirm('Restore under the existing event-management rules.','Restore event')],
 'record-attendance':['Edit attendance',`<form class="stack" data-confirm-form="Attendance saved">${field('Member',select('attendance-member',['Alex Chen','Jordan Lee','Sam Rivera']))}${field('Arrival (Los Angeles)',input('arrival','2026-11-07T10:02','datetime-local'))}${field('Departure (Los Angeles)',input('departure','','datetime-local'),'Empty = still here')}<details><summary>Daylight-saving time</summary><div>${field('Repeated wall time',select('attendance-dst',['Reject ambiguity','Earlier occurrence','Later occurrence']))}</div></details><button class="button primary">Save</button></form>`],
 'refresh-attendance':['Refresh attendance',`<p>Sample attendance is unchanged. In the application, reload only this section, preserve filters and distinguish an error from an empty roster.</p>`],
 'build-correction':['Build attendance correction',`<form class="stack" data-confirm-form="Build correction saved">${field('Member',select('build-member',['Alex Chen','Jordan Lee']))}${field('Session',select('build-session',['Workshop · Nov 2']))}${field('Check-in (Los Angeles)',input('correction-start','2026-11-02T15:35','datetime-local'))}${field('Check-out (Los Angeles)',input('correction-end','2026-11-02T17:35','datetime-local'))}<label class="checkline"><input name="credit-override" type="checkbox">Enable credit override</label><p class="small muted">Keep the existing explicit boolean override; this is not an arbitrary-hours field. Save actual timestamps; credit is recalculated by the server.</p><button class="button primary">Save correction</button></form>`],
 'submission-new':['What are you submitting?',`<div class="stack">${button('Optix Passion Initiative (OPI)','opi-new',true)}${button('Individual outreach hours','outreach-log')}${button('Purchase request','purchase-new')}</div>`],
 'opi-document':['Document access & preview',`<div class="notice warning"><div><strong>Sample external-document access state</strong><p>No real document is linked in this prototype. In the application, preserve Open in Google Docs and Reload preview if the embed is blocked.</p></div></div><p class="small muted" style="margin-top:18px">Submitted URLs/summaries are versioned. A live external document is not immutable. Request access or changes explicitly; do not treat a failed preview as missing content.</p>`],
 'opi-versions':['Choose retained submission',`<div class="stack"><button class="button" data-notice="Sample version 2 selected: volunteer plan added.">Version 2 · Nov 1 · Resubmitted</button><button class="button" data-notice="Sample version 1 selected: original summary, before volunteer-plan feedback.">Version 1 · Oct 29 · Original submission</button><p class="small muted">The actual UI should display the retained version title, URL, summary and timestamp together.</p></div>`],
 'convert-opi':['Create event from approved OPI',`<p class="small muted" style="margin-bottom:18px">Available after approval to an authorized manager. Preserve the OPI/event link and require event details; approval itself does not schedule an event.</p><form class="stack" data-confirm-form="Linked outreach event created">${field('Event title',input('converted-title','Library robotics day'))}${field('Location',input('converted-location','Central Library'))}${field('Start (Los Angeles)',input('converted-start','2026-11-07T10:00','datetime-local'))}${field('End (Los Angeles)',input('converted-end','2026-11-07T12:00','datetime-local'))}<button class="button primary">Create linked outreach event</button></form>`],
 'receipt':['Private receipt',`<div class="document-sheet"><p class="eyebrow">Sample receipt</p><h3>Intake bearings</h3><hr class="divider"><p>4 × bearing · $9.60</p><p><strong>Total · $38.40</strong></p></div>`],
 'oauth':['External sign-in',`<p>The existing Google/Microsoft sign-in paths remain available. This design prototype does not contact either provider or open an authentication session.</p>${button('View admission states','account-status')}`],
 'approval-status':['Check account state',`<p>Sample account remains pending approval. In the application, refresh verified account state and navigate to Home only after admission succeeds.</p>${button('Back to account states','account-status')}`]
};
function openModal(id){const item=modalDefs[id];if(!item){notify('This interaction is not included in the review sample.');return;}lastFocus=document.activeElement;document.querySelector('#modal-title').textContent=item[0];document.querySelector('#modal-body').innerHTML=item[1];const d=document.querySelector('#modal');if(!d.open)d.showModal();}
window.U.openModal=openModal;
function closeModal(){document.querySelector('#modal').close();lastFocus?.focus();}
function renderCheckedIn(){const el=document.querySelector('#checkin-state');if(el)el.innerHTML=`<div class="checkin-summary">${badge('Checked in','success')}<span>Arrived 3:35 PM</span></div><h2>Check out of Workshop</h2><div class="checkin-methods"><button class="method-button" data-modal="scan-qr"><span class="method-icon">${window.U.icon('qr')}</span><strong>Scan QR</strong><span>Room code</span></button><button class="method-button" data-modal="gps-checkin"><span class="method-icon">${window.U.icon('location')}</span><strong>Use location</strong><span>Workshop</span></button></div>`;}
document.addEventListener('click',e=>{const t=e.target.closest('[data-modal],[data-close],[data-notice],[data-go],[data-mark-read],[data-checkout],[data-clear-groups]');if(!t)return;if(t.hasAttribute('data-modal')){e.preventDefault();openModal(t.dataset.modal);if(['scan-qr','gps-checkin'].includes(t.dataset.modal)&&checkedIn){document.querySelector('#modal-title').textContent='Check out · Workshop';const form=document.querySelector('#modal [data-checkin]');if(form){form.removeAttribute('data-checkin');form.dataset.sessionCheckout='';form.querySelector('button').textContent='Confirm check-out';}}}else if(t.hasAttribute('data-close'))closeModal();else if(t.hasAttribute('data-notice')){e.preventDefault();notify(t.dataset.notice);}else if(t.hasAttribute('data-go'))location.hash=t.dataset.go;else if(t.hasAttribute('data-clear-groups'))t.closest('fieldset').querySelectorAll('input').forEach(x=>x.checked=false);else if(t.hasAttribute('data-mark-read')){document.querySelectorAll('#notification-list .badge').forEach(x=>x.remove());t.textContent='Marked read';notify('Notifications marked read');}else if(t.hasAttribute('data-checkout'))finishCheckout();});
function finishCheckout(){checkedIn=false;if(document.querySelector('#modal').open)closeModal();document.querySelector('#checkin-state').innerHTML=`<div class="notice"><strong>Checked out · 2.00 h</strong>${button('View attendance','activity-history')}</div>`;notify('Checked out of Workshop');}
document.addEventListener('submit',e=>{const f=e.target;if(f.matches('[data-session-checkout]')){e.preventDefault();finishCheckout();}else if(f.matches('[data-checkin]')){e.preventDefault();checkedIn=true;if(document.querySelector('#modal').open)closeModal();renderCheckedIn();notify('Checked in to Workshop');}else if(f.matches('[data-confirm-form]')){e.preventDefault();const title=f.dataset.confirmForm;document.querySelector('#modal-body').innerHTML=`<div class="notice"><strong>${esc(title)}</strong></div><div class="actions" style="margin-top:20px"><button class="button primary" data-close>Done</button></div>`;notify(title);}else if(f.matches('[data-filter-form]')){e.preventDefault();const groups=[...f.querySelectorAll('input[type=checkbox]:checked')].map(x=>x.parentElement.textContent.trim());closeModal();const list=document.querySelector('#task-list');if(list){if(!groups.length&&route!=='work-global')list.innerHTML='<div class="empty"><h2>No groups selected</h2><button class="button" data-modal="task-filters">Choose groups</button></div>';else notify('Filters updated');}}else if(f.matches('[data-demo-form]')){e.preventDefault();notify(f.dataset.demoForm);let result=f.querySelector('[data-form-result]');if(!result){result=document.createElement('div');result.className='notice';result.dataset.formResult='';result.setAttribute('role','status');f.append(result);}result.textContent=f.dataset.demoForm;}});
document.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-task-search]'))document.querySelectorAll('#task-list .row').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(t.value.toLowerCase()));if(t.matches('[data-roster-search]'))document.querySelectorAll('#roster tr').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(t.value.toLowerCase()));if(t.matches('[data-directory-search]'))document.querySelectorAll('tbody tr').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(t.value.toLowerCase()));});
document.addEventListener('change',e=>{if(e.target.matches('[data-rsvp]'))document.querySelector('#rsvp-status').textContent=e.target.checked?'Sample RSVP: planning to attend':'Sample RSVP: not planning to attend';});
window.startPrototype=()=>{document.querySelector('#role').addEventListener('change',e=>{role=e.target.value;render();notify(`Previewing ${e.target.selectedOptions[0].textContent}. Sample permissions only.`);});document.querySelector('#theme').addEventListener('click',()=>document.documentElement.classList.toggle('dark'));document.querySelector('#modal').addEventListener('close',()=>lastFocus?.focus());window.addEventListener('hashchange',()=>{if(document.querySelector('#modal').open)document.querySelector('#modal').close();render();window.scrollTo(0,0);document.querySelector('#main').focus({preventScroll:true});});render();};
document.querySelector('.topbar a[aria-label^="Notifications"]').innerHTML=iconSVG('notifications')+'<span class="notification-dot"></span>';
})();
document.addEventListener('click',event=>{if(event.target.closest('[data-theme-toggle]'))document.documentElement.classList.toggle('dark');});
document.addEventListener('click',event=>{const menu=document.querySelector('.account-nav');if(!menu.contains(event.target))menu.open=false;});
document.addEventListener('keydown',event=>{const menu=document.querySelector('.account-nav');if(event.key==='Escape'&&menu.open){menu.open=false;menu.querySelector('summary').focus();}});
